 "content": "from collections import Counter, deque


def transform(grid):
    """Encode each non-background horizontal object as one cell, by color."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            objects.append(color)
    encoded = sorted(objects, reverse=True)[:6]
    encoded += [0] * (6 - len(encoded))
    return [encoded[:3], encoded[3:]]
